import{_ as s,C as t,o as e,c as g,j as i,E as r,a as l,a2 as o}from"./chunks/framework.C21TwvGF.js";const R=JSON.parse(`{"title":"8-dars (Mentor). Ranglar nazariyasi va dizayn asoslari (1-qism): RGB va CMYK, rang g'ildiragi va rang psixologiyasi","description":"","frontmatter":{"title":"8-dars (Mentor). Ranglar nazariyasi va dizayn asoslari (1-qism): RGB va CMYK, rang g'ildiragi va rang psixologiyasi","layout":"doc","sidebar":false,"aside":false,"outline":false,"kind":"mentor_dars","dars":{"sinf":{"name":"9-sinf (Game)","link":"/mentor/9-sinf-game/"},"week":{"n":3,"link":"/mentor/9-sinf-game/hafta-03/"},"g":8,"title":"Ranglar nazariyasi va dizayn asoslari (1-qism): RGB va CMYK, rang g'ildiragi va rang psixologiyasi","lead":"Ranglar nazariyasi va dizayn asoslari (1-qism): RGB va CMYK, rang g'ildiragi va rang psixologiyasi","slide":"/slaydlar/9-sinf-game/hafta-03/dars-2.html","test":"/slaydlar/9-sinf-game/hafta-03/dars-2-test.html","student_link":"/9-sinf-game/hafta-03/dars-2","tabs":[{"g":7,"link":"/mentor/9-sinf-game/hafta-03/dars-1","current":false},{"g":8,"link":"/mentor/9-sinf-game/hafta-03/dars-2","current":true},{"g":9,"link":"/mentor/9-sinf-game/hafta-03/dars-3","current":false}],"prev":{"g":7,"title":"Photoshop interfeysi va vositalari (3-qism): Qatlamlar bilan amaliy ishlash va assetlar kollaji","link":"/mentor/9-sinf-game/hafta-03/dars-1"},"next":{"g":9,"title":"Ranglar nazariyasi va dizayn asoslari (2-qism): Color Picker, Swatches va Gradient bilan ishlash","link":"/mentor/9-sinf-game/hafta-03/dars-3"}}},"headers":[],"relativePath":"mentor/9-sinf-game/hafta-03/dars-2.md","filePath":"mentor/9-sinf-game/hafta-03/dars-2.md"}`),h={name:"mentor/9-sinf-game/hafta-03/dars-2.md"},d={class:"blk"},m={id:"dars-rejasi",tabindex:"-1"},u={class:"blk"},q={id:"mentor-konspekti",tabindex:"-1"},y={class:"blk"},k={id:"amaliy-topshiriqlar-va-yechimlar",tabindex:"-1"},v={class:"blk"},b={id:"tezkor-nazorat-savollari",tabindex:"-1"},p={class:"blk"},c={id:"keng-tarqalgan-xatolar-va-ularning-oldini-olish",tabindex:"-1"};function f(z,a,x,_,P,S){const n=t("Icon");return e(),g("div",null,[i("div",d,[i("h2",m,[r(n,{name:"file-text"}),a[0]||(a[0]=l(" Dars rejasi ",-1)),a[1]||(a[1]=i("a",{class:"header-anchor",href:"#dars-rejasi","aria-label":'Permalink to "<Icon name="file-text" /> Dars rejasi"'},"​",-1))]),a[2]||(a[2]=o("<ul><li><strong>Darsning maqsadi:</strong> O&#39;quvchilarga ranglar nazariyasining fundamental asoslarini — raqamli (RGB) va poligrafik (CMYK) rang modellarini, Yoxannes Ittenning rang g&#39;ildiragini (birlamchi, ikkilamchi, uchlamchi ranglar), asosiy ranglar uyg&#39;unligi sxemalarini (komplementar, analog, triada) hamda o&#39;yin atmosferasini yaratishda rang psixologiyasining ta&#39;sirini o&#39;rgatish.</li><li><strong>Kutiladigan natija:</strong> O&#39;quvchilar raqamli o&#39;yin grafikasi uchun RGB modelini nima sababdan ishlatish kerakligini tushunadi; rang g&#39;ildiragidan foydalanib o&#39;zaro uyg&#39;un rang palitrasi tuza oladi; o&#39;yin qahramonlari, interfeysi va muhitiga mos emotsional rang psixologiyasini to&#39;g&#39;ri tanlay oladi.</li><li><strong>Vaqt taqsimoti:</strong><ul><li>O&#39;tgan mavzuni takrorlash (Assetlar kollaji va qatlamlar): 10 daqiqa</li><li>Yangi mavzu: RGB vs CMYK, rang g&#39;ildiragi (Itten) va issiq/sovuq ranglar: 25 daqiqa</li><li>Rang uyg&#39;unliklari (Harmonies) va o&#39;yinda rang psixologiyasi: 25 daqiqa</li><li>Amaliy topshiriqlar tahlili: 15 daqiqa</li><li>Dars xulosasi va nazorat savollari: 5 daqiqa</li></ul></li></ul><hr>",2))]),i("div",u,[i("h2",q,[r(n,{name:"file-text"}),a[3]||(a[3]=l(" Mentor konspekti ",-1)),a[4]||(a[4]=i("a",{class:"header-anchor",href:"#mentor-konspekti","aria-label":'Permalink to "<Icon name="file-text" /> Mentor konspekti"'},"​",-1))]),a[5]||(a[5]=o('<h3 id="_1-raqamli-va-chop-etish-modellari-rgb-vs-cmyk" tabindex="-1">1. Raqamli va chop etish modellari: RGB vs CMYK <a class="header-anchor" href="#_1-raqamli-va-chop-etish-modellari-rgb-vs-cmyk" aria-label="Permalink to &quot;1. Raqamli va chop etish modellari: RGB vs CMYK&quot;">​</a></h3><ul><li><strong>RGB (Red, Green, Blue) — Additiv model:</strong><ul><li>Yorug&#39;lik nurlarining qo&#39;shilishiga asoslangan.</li><li>Kompyuter monitorlari, telefon ekranlari, televizorlar va barcha raqamli o&#39;yinlar uchun yagona standart.</li><li>Barcha 3 rang 100% qo&#39;shilsa — oq rang (White) hosil bo&#39;ladi. Har bir kanal 0 dan 255 gacha qiymatga ega (jami 16.7 million rang).</li></ul></li><li><strong>CMYK (Cyan, Magenta, Yellow, Key/Black) — Subtraktiv model:</strong><ul><li>Bo&#39;yoqlarning yorug&#39;likni yutishiga asoslangan.</li><li>Bosmaxona, printer va qog&#39;oz mahsulotlari (posterlar, o&#39;yin qutilari) uchun ishlatiladi.</li><li>Bo&#39;yoqlar qo&#39;shilgan sari qorayadi.</li></ul></li><li><strong>Qat&#39;iy qoida:</strong> O&#39;yin dvijoklari (Unity, Unreal, Godot) faqat RGB modelidagi tekstura va spraytlarni qabul qiladi. Agar Photoshopda adashib CMYK ochilsa, o&#39;yin ranglari so&#39;nib, dvijokda xato ko&#39;rsatadi.</li></ul><h3 id="_2-yoxannes-itten-rang-g-ildiragi-color-wheel" tabindex="-1">2. Yoxannes Itten rang g&#39;ildiragi (Color Wheel) <a class="header-anchor" href="#_2-yoxannes-itten-rang-g-ildiragi-color-wheel" aria-label="Permalink to &quot;2. Yoxannes Itten rang g&#39;ildiragi (Color Wheel)&quot;">​</a></h3><p>Ranglar 3 ta avlodga bo&#39;linadi:</p><ol><li><strong>Asosiy (Primary) ranglar:</strong> Qizil (Red), Sariq (Yellow), Ko&#39;k (Blue) — ularni boshqa ranglarni aralashtirib hosil qilib bo&#39;lmaydi.</li><li><strong>Ikkilamchi (Secondary) ranglar:</strong> Asosiy ranglarni 1:1 aralashtirishdan hosil bo&#39;ladi: <ul><li>Qizil + Sariq = To&#39;q sariq (Orange)</li><li>Sariq + Ko&#39;k = Yashil (Green)</li><li>Ko&#39;k + Qizil = Binafsha (Purple)</li></ul></li><li><strong>Uchlamchi (Tertiary) ranglar:</strong> Asosiy va qo&#39;shni ikkilamchi rang aralashmasi (Qizil-to&#39;q sariq, Sariq-yashil, Ko&#39;k-binafsha va h.k.).</li></ol><h3 id="_3-issiq-va-sovuq-ranglar-optikasi" tabindex="-1">3. Issiq va sovuq ranglar optikasi <a class="header-anchor" href="#_3-issiq-va-sovuq-ranglar-optikasi" aria-label="Permalink to &quot;3. Issiq va sovuq ranglar optikasi&quot;">​</a></h3><ul><li><strong>Issiq ranglar (Qizil, Sariq, Olovrang):</strong><ul><li>Olov, quyosh va harakat ramzi.</li><li>Vizual optik qonun: Issiq ranglar tomoshabinga <strong>yaqinroq</strong> ko&#39;rinadi.</li><li>O&#39;yinda: Qahramon, jangovar qurollar, &quot;Attack&quot; tugmasi, xavf zonasi.</li></ul></li><li><strong>Sovuq ranglar (Ko&#39;k, Yashil, Binafsha):</strong><ul><li>Suv, muz, osmon va xotirjamlik ramzi.</li><li>Vizual optik qonun: Sovuq ranglar ko&#39;zga <strong>uzoqlashgandek</strong> tuyuladi.</li><li>O&#39;yinda: Uzoq fon manzaralari, tuman, sirli g&#39;orlar, sehr energiyasi (Mana).</li></ul></li></ul><h3 id="_4-ranglar-uyg-unligi-sxemalari-color-harmonies" tabindex="-1">4. Ranglar uyg&#39;unligi sxemalari (Color Harmonies) <a class="header-anchor" href="#_4-ranglar-uyg-unligi-sxemalari-color-harmonies" aria-label="Permalink to &quot;4. Ranglar uyg&#39;unligi sxemalari (Color Harmonies)&quot;">​</a></h3><p>Professional geym-artistlar ranglarni ko&#39;r-ko&#39;rona emas, matematik formulalar bo&#39;yicha tanlaydilar:</p><ol><li><strong>Monoxrom (Monochromatic):</strong> Bitta rangning turli ochlik va to&#39;qlik darajalari (soya va yorug&#39;lik). Juda sokin va nafis.</li><li><strong>Komplementar (Complementary):</strong> Rang g&#39;ildiragida bir-biriga qarama-qarshi turgan ikki rang (Qizil va Yashil, Ko&#39;k va To&#39;q sariq). Maksimal kontrast beradi. O&#39;yin qahramonini fondan keskin ajratish uchun eng yaxshi usul.</li><li><strong>Analog (Analogous):</strong> G&#39;ildirakda yonma-yon turgan 3 ta rang (masalan, Sariq, Sariq-olovrang, Olovrang). Tabiiy va ko&#39;zga yoqimli muhit yaratadi.</li><li><strong>Triadik (Triadic):</strong> Doirada teng tomonli uchburchak hosil qiluvchi 3 rang (Qizil, Sariq, Ko&#39;k). Rang-barang, jonli retro yoki arkada o&#39;yinlari uchun a&#39;lo tanlov.</li></ol><h3 id="_5-o-yin-dizaynida-rang-psixologiyasi" tabindex="-1">5. O&#39;yin dizaynida rang psixologiyasi <a class="header-anchor" href="#_5-o-yin-dizaynida-rang-psixologiyasi" aria-label="Permalink to &quot;5. O&#39;yin dizaynida rang psixologiyasi&quot;">​</a></h3><ul><li><strong>Qizil:</strong> Qon, xavf, ehtiros, jang. Salomatlik paneli (HP) kritik darajaga tushganda miltillaydi. Dushmanlar va &quot;Boss&quot; personajlar ko&#39;pincha qizil rangda bo&#39;ladi.</li><li><strong>Yashil:</strong> Hayot, tabiat, salomatlik, xavfsizlik. To&#39;la HP bar, o&#39;simliklar, &quot;Save&quot; va &quot;Start&quot; tugmalari.</li><li><strong>Sariq / Oltin:</strong> Boylik, tangalar, quvonch, chaqmoq, ogohlantirish (Warning).</li><li><strong>Ko&#39;k:</strong> Ishonch, do&#39;stlik, sovuq aql, suv, sehr kuchi (Mana bar).</li><li><strong>Binafsha:</strong> Sehr, afsun, hashamat, mistika, nodir va afsonaviy o&#39;lja (Epic/Legendary Loot).</li><li><strong>Oq va Qora:</strong> Oq — poklik, yorug&#39;lik, ilohiy kuch; Qora — qorong&#39;ulik, yovuzlik, dramatizm, o&#39;lim.</li></ul><hr>',13))]),i("div",y,[i("h2",k,[r(n,{name:"file-text"}),a[6]||(a[6]=l(" Amaliy topshiriqlar va yechimlar ",-1)),a[7]||(a[7]=i("a",{class:"header-anchor",href:"#amaliy-topshiriqlar-va-yechimlar","aria-label":'Permalink to "<Icon name="file-text" /> Amaliy topshiriqlar va yechimlar"'},"​",-1))]),a[8]||(a[8]=o('<h3 id="_1-topshiriq-komplementar-rang-sxemasi-bilan-qahramonni-fondan-ajratish-oson" tabindex="-1">1-topshiriq. Komplementar rang sxemasi bilan qahramonni fondan ajratish (oson) <a class="header-anchor" href="#_1-topshiriq-komplementar-rang-sxemasi-bilan-qahramonni-fondan-ajratish-oson" aria-label="Permalink to &quot;1-topshiriq. Komplementar rang sxemasi bilan qahramonni fondan ajratish (oson)&quot;">​</a></h3><p>O&#39;yin zaminida qalin yashil o&#39;tloq va yashil daraxtlar bor. Agar o&#39;yin qahramoni ham yashil kiyimda bo&#39;lsa, u fonda yo&#39;qolib ketadi. Komplementar kontrast qonuniga binoan, qahramon kiyimining asosiy rangini qanday tanlash kerak va bu qanday natija beradi?</p><p><strong>Yechim:</strong></p><ol><li>Itten rang g&#39;ildiragiga qaraladi: Yashil rangning to&#39;g&#39;ridan-to&#39;g&#39;ri qarama-qarshisida (180 daraja) <strong>Qizil (yoki Qizil-olovrang)</strong> joylashgan.</li><li>Qahramonning kiyimi yoki qalqoni yorqin qizil rangga bo&#39;yaladi.</li><li><em>Natija:</em> Ko&#39;z to&#39;r pardasi qarama-qarshi to&#39;lqin uzunliklarini bir vaqtda qabul qilganda maksimal kontrast hosil bo&#39;ladi. Qahramon yashil o&#39;rmon fonida darhol yaqqol ko&#39;zga tashlanadi va o&#39;yinchi uni hech qachon yo&#39;qotib qo&#39;ymaydi.</li></ol><h3 id="_2-topshiriq-rpg-o-yini-uchun-3-xil-status-panelining-rang-palitrasi-o-rta" tabindex="-1">2-topshiriq. RPG o&#39;yini uchun 3 xil status panelining rang palitrasi (o&#39;rta) <a class="header-anchor" href="#_2-topshiriq-rpg-o-yini-uchun-3-xil-status-panelining-rang-palitrasi-o-rta" aria-label="Permalink to &quot;2-topshiriq. RPG o&#39;yini uchun 3 xil status panelining rang palitrasi (o&#39;rta)&quot;">​</a></h3><p>Siz 2D RPG o&#39;yinining foydalanuvchi interfeysini (HUD) loyihalayapsiz. Unda 3 ta ko&#39;rsatkich bor:</p><ul><li><ol><li>Salomatlik (Health Points — HP);</li></ol></li><li><ol start="2"><li>Sehr energiyasi (Mana Points — MP);</li></ol></li><li><ol start="3"><li>Qahramon charchog&#39;i / chidamliligi (Stamina). Rang psixologiyasi va o&#39;yin standartlari asosida har bir panel uchun asosiy rang va uning fon kontrastini belgilab bering.</li></ol></li></ul><p><strong>Yechim:</strong></p><ol><li><strong>Health (HP):</strong> Asosiy rang — <strong>Qizil</strong> (qon va hayot ramzi). To&#39;q qizil zamin ustida yorqin yoqut qizil to&#39;ldiruvchi chiziq.</li><li><strong>Mana (MP):</strong> Asosiy rang — <strong>To&#39;q ko&#39;k / Safir</strong> (sehrli aql va ruhiy quvvat ramzi). Qorong&#39;i g&#39;orlarda ham moviy porlab turadi.</li><li><strong>Stamina (Chidamlilik):</strong> Asosiy rang — <strong>Yashil yoki Sariq-yashil</strong> (jismoniy quvvat va harakat dinamikasi). Chopganda tez kamayib, turganda yana to&#39;ladi.</li><li><em>Barcha panellarning ramkasi:</em> Neytral to&#39;q kulrang yoki oltin naqshli qilib ishlanadi, shunda rangli chiziqlar aniq o&#39;qiladi.</li></ol><h3 id="_3-topshiriq-fantastik-kiberpank-o-yini-uchun-triadik-rang-sxemasini-tuzish-qiyin" tabindex="-1">3-topshiriq. Fantastik kiberpank o&#39;yini uchun Triadik rang sxemasini tuzish (qiyin) <a class="header-anchor" href="#_3-topshiriq-fantastik-kiberpank-o-yini-uchun-triadik-rang-sxemasini-tuzish-qiyin" aria-label="Permalink to &quot;3-topshiriq. Fantastik kiberpank o&#39;yini uchun Triadik rang sxemasini tuzish (qiyin)&quot;">​</a></h3><p>Kelajak shahri bo&#39;ylab kechuvchi kiberpank (Cyberpunk) janridagi o&#39;yin uchun qorong&#39;i neon atmosferasi talab etiladi. Triada (Triadic) qoidasiga asoslanib, bir-biriga teng masofadagi 3 ta yorqin neon rangdan iborat rang palitrasini aniqlang va har bir rangning sahnadagi vazifasini taqsimlang.</p><p><strong>Yechim:</strong></p><ol><li><strong>Ranglar tanlovi (Neon Triada):</strong><ul><li><ol><li>Neon Pushti/Binafsha (Magenta / Neon Pink — taxminan #FF007F);</li></ol></li><li><ol start="2"><li>Neon Moviy (Cyan / Electric Blue — taxminan #00F0FF);</li></ol></li><li><ol start="3"><li>Neon Sariq (Acid Yellow / Neon Lime — taxminan #FFE600).</li></ol></li></ul></li><li><strong>Vazifalar taqsimoti:</strong><ul><li><em>Fon va shahar muhiti (60%):</em> To&#39;q qora-ko&#39;k fon ustida uzoq binolarning deraza va reklamalarida Magenta/Pushti nurlar.</li><li><em>Interfeys va yordamchi obyektlar (30%):</em> HUD ramkalari, qurollarning lazer nishonlari va xavfsiz zonalar Cyan/Moviy rangda.</li><li><em>Aktsent va diqqat markazi (10%):</em> Interaktiv eshiklar, portlovchi bochkalar va bosh dushman nishonlari Acid Yellow rangida porlaydi.</li></ul></li></ol><hr>',14))]),i("div",v,[i("h2",b,[r(n,{name:"file-text"}),a[9]||(a[9]=l(" Tezkor nazorat savollari ",-1)),a[10]||(a[10]=i("a",{class:"header-anchor",href:"#tezkor-nazorat-savollari","aria-label":'Permalink to "<Icon name="file-text" /> Tezkor nazorat savollari"'},"​",-1))]),a[11]||(a[11]=o("<ol><li>Nima sababdan o&#39;yin grafikasini CMYK emas, balki faqat RGB rejimida yaratish shart? <ul><li><em>Javob:</em> Chunki barcha o&#39;yinlar elektron ekranlarda (monitor, telefon) ko&#39;rsatiladi, ekranlar esa additiv yorug&#39;lik nurlari (RGB) bilan ishlaydi. CMYK esa faqat qog&#39;ozga chop etish uchun mo&#39;ljallangan.</li></ul></li><li>Qaysi ranglar Yoxannes Itten g&#39;ildiragida asosiy (birlamchi) hisoblanadi? <ul><li><em>Javob:</em> Qizil, Sariq va Ko&#39;k.</li></ul></li><li>Rang g&#39;ildiragida bir-biriga 180 gradus qarama-qarshi turgan ranglar juftligi qanday ataladi? <ul><li><em>Javob:</em> Komplementar (to&#39;ldiruvchi) ranglar.</li></ul></li><li>O&#39;yinlarda afsonaviy, juda qimmatbaho sehrli qurollar (Legendary loot) an&#39;anaviy ravishda qaysi rang bilan belgilanadi? <ul><li><em>Javob:</em> Binafsha (Purple) yoki Oltin-sariq rang.</li></ul></li></ol><hr>",2))]),i("div",p,[i("h2",c,[r(n,{name:"file-text"}),a[12]||(a[12]=l(" Keng tarqalgan xatolar va ularning oldini olish ",-1)),a[13]||(a[13]=i("a",{class:"header-anchor",href:"#keng-tarqalgan-xatolar-va-ularning-oldini-olish","aria-label":'Permalink to "<Icon name="file-text" /> Keng tarqalgan xatolar va ularning oldini olish"'},"​",-1))]),a[14]||(a[14]=i("ul",null,[i("li",null,[i("strong",null,`Haddan tashqari ko'p to'yingan ranglar ishlatish ("Kislotali dizayn"):`),l(" O'quvchilar barcha obyektlarni eng yorqin, 100% to'yingan ranglarga bo'yab yuborishadi. Natijada o'yinchining ko'zi 2 daqiqada charchaydi. 60-30-10 qoidasiga amal qilish kerak: 60% neytral/baza rang, 30% ikkilamchi rang, faqat 10% yorqin aktsent!")]),i("li",null,[i("strong",null,"Rang kontrasti yetishmasligi:"),l(" Matn rangi fon rangi bilan bir xil yorqinlikda bo'lsa, o'yinchi matnni o'qiy olmaydi (masalan, qizil zamin ustiga to'q jigarrang yozuv). Har doim yorqinlik (Value) kontrastini tekshirish lozim.")]),i("li",null,[i("strong",null,"Issiq va sovuq ranglar chuqurligini inobatga olmaslik:"),l(" Agar uzoqdagi tog'lar qizil-olovrang, oldingi qahramon esa xira ko'k qilib chizilsa, perspektiva buziladi — tog'lar ko'zga yaqinroq ko'rinib qoladi.")])],-1))])])}const j=s(h,[["render",f]]);export{R as __pageData,j as default};
